// Fetch WhatsApp only lists raw messages; narrow to image-type messages that carry a non-empty
// caption, and pull out just the fields the rest of the media-fetch chain needs.
const out = [];
for (const item of $input.all()) {
  const msg = item.json;
  if (msg.type !== 'image') continue;
  const caption = (msg.image && msg.image.caption) || msg.caption;
  if (!caption) continue;
  const mediaId = msg.image && msg.image.id;
  if (!mediaId) continue;
  out.push({ json: { id: msg.id, mediaId, caption } });
}
return out;

// Response from Get Media URL replaced item.json (its own 'id' field is the media ID again,
// echoed back by the API -- not the WhatsApp message ID), so pull id/mediaId/caption back from
// the pre-call state and keep url/mime_type from this call.
const upstream = $('Filter Image Messages').all();
return $input.all().map((item, i) => ({ json: { ...upstream[i].json, mediaUrl: item.json.url, mimeType: item.json.mime_type } }));

// A binary/file HTTP response may not carry the incoming JSON forward, so pull
// id/mediaId/caption/mimeType back from the pre-call state and keep the binary data attached.
const upstream = $('Reattach Media URL Fields').all();
return $input.all().map((item, i) => ({ json: { ...upstream[i].json }, binary: item.binary }));

// Per-post dedup: create a per-platform entry for any post not seen before.
const store = $getWorkflowStaticData('global');
store.published = store.published || {};
const out = [];
for (const item of $input.all()) {
  const id = item.json.id || item.json.imageUrl;
  if (!id) continue;
  if (!store.published[id]) {
    store.published[id] = { instagram: false, facebook: false, linkedin: false };
  }
  out.push({ json: { ...item.json, dedupId: id } });
}
return out;

// Response from Upload to Public Host replaced item.json (same bug class already fixed once
// before for the LinkedIn publish node -- see the comment in Mark LI Published), so pull
// dedupId/caption back from the pre-call state and independently construct the public-read URL.
// Note the path prefix here is /object/public/nmd-social/... (with /public/), which differs from
// the write URL on Upload to Public Host (/object/nmd-social/..., no /public/) -- Supabase Storage
// uses different prefixes for write vs. public-read, but both must agree on the dedupId filename.
const upstream = $('Dedup Check').all();
return $input.all().map((item, i) => {
  const src = upstream[i].json;
  return { json: { ...src, publicUrl: `https://rqdieyainwiyjupgjcsd.supabase.co/storage/v1/object/public/nmd-social/${src.dedupId}.jpg` } };
});

// IF: skip if already published to Instagram this post.
const store = $getWorkflowStaticData('global');
return $input.all().filter(item => !(store.published[item.json.dedupId] || {}).instagram);

// Response from IG Publish replaced item.json, so pull dedupId/caption back from the pre-call state and add the success flag.
const upstream = $('IF Instagram Pending').all();
return $input.all().map((item, i) => ({ json: { ...upstream[i].json, igPublished: true } }));

// IF: skip if already published to Facebook this post.
const store = $getWorkflowStaticData('global');
return $input.all().filter(item => !(store.published[item.json.dedupId] || {}).facebook);

// Response from FB Publish Photo replaced item.json, so pull dedupId/caption back from the pre-call state and add the success flag.
const upstream = $('IF Facebook Pending').all();
return $input.all().map((item, i) => ({ json: { ...upstream[i].json, fbPublished: true } }));

// IF: skip if already published to LinkedIn this post.
const store = $getWorkflowStaticData('global');
return $input.all().filter(item => !(store.published[item.json.dedupId] || {}).linkedin);

// Response from the Make webhook replaced item.json, so pull dedupId/caption back from the pre-call state and add the success flag.
const upstream = $('IF LinkedIn Pending').all();
return $input.all().map((item, i) => ({ json: { ...upstream[i].json, liPublished: true } }));

// Save per-platform flags only for branches that actually ran and succeeded this cycle.
const store = $getWorkflowStaticData('global');
for (const item of $input.all()) {
  const id = item.json.dedupId;
  if (!id || !store.published[id]) continue;
  if (item.json.igPublished) store.published[id].instagram = true;
  if (item.json.fbPublished) store.published[id].facebook = true;
  if (item.json.liPublished) store.published[id].linkedin = true;
}
return $input.all();
